      setData(response.data.values);
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : 'Failed to load placeholder data.'
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (!cancelled) {
        await fetchData();
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

